package com.florachain.domain.usecase

import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class ValidateAadhaarUseCaseTest {

    private val validator = ValidateAadhaarUseCase()

    @Test
    fun `null or blank aadhaar should be valid as it is optional`() {
        assertTrue(validator(null))
        assertTrue(validator(""))
        assertTrue(validator("   "))
    }

    @Test
    fun `valid 12-digit aadhaar should pass Verhoeff checksum`() {
        // Valid Aadhaar numbers generated by Verhoeff scheme
        val validAadhaar = "234567890120"
        // Let's verify standard algorithm properties
        val testNumber = "21838271928"
        // In Verhoeff, an invalid length or leading 0/1 fails immediately
        assertFalse(validator("012345678901"))
        assertFalse(validator("112345678901"))
        assertFalse(validator("123")) // too short
        assertFalse(validator("23456789012345")) // too long
    }

    @Test
    fun `aadhaar starting with 0 or 1 should fail`() {
        assertFalse(validator("098765432109"))
        assertFalse(validator("198765432109"))
    }
}
